// ============================================================
// TONE MINIMAL PAIRS — words that differ only by tone
// ============================================================

class ToneMinimalPair {
  final String word1;
  final String english1;
  final String tone1;
  final String word2;
  final String english2;
  final String tone2;
  final String? word3;
  final String? english3;
  final String? tone3;

  const ToneMinimalPair({
    required this.word1,
    required this.english1,
    required this.tone1,
    required this.word2,
    required this.english2,
    required this.tone2,
    this.word3,
    this.english3,
    this.tone3,
  });
}

